#include <iostream>
#include <string>

class Account {
public:
    int accountNumber;
protected:
    double balance;
private:
    int pin;
public:
    Account(int accNum, double bal, int p) : accountNumber(accNum), balance(bal), pin(p) {}
};

class SavingsAccount : public Account {
public:
    SavingsAccount(int accNum, double bal, int p) : Account(accNum, bal, p) {}

    void display() {
        std::cout << "Savings Account: " << accountNumber << " " << balance << std::endl;
    }
};

class SecureAccount : private Account {
public:
    SecureAccount(int accNum, double bal, int p) : Account(accNum, bal, p) {}

    void display() {
        std::cout << "Secure Account: Access Restricted " << std::endl;
    }
};

int main() {
    int accNum, pin;
    double bal;
    std::cin >> accNum >> bal >> pin;

    SavingsAccount sa(accNum, bal, pin);
    SecureAccount seca(accNum, bal, pin);

    sa.display();
    seca.display();

    sa.display();
    seca.display();

    return 0;
}
